-- Gold Query
SELECT t1.buildUpPlaySpeed FROM Team_Attributes AS t1 INNER JOIN Team AS t2 ON t1.team_api_id = t2.team_api_id ORDER BY t1.buildUpPlayDribbling ASC, t1.id NULLS LAST, t2.id NULLS LAST LIMIT 4;

