-- Prediction Query
SELECT team_long_name, buildUpPlaySpeed FROM Team_Attributes INNER JOIN Team ON Team_Attributes.team_api_id = Team.team_api_id ORDER BY buildUpPlaySpeed DESC, Team_Attributes.id NULLS LAST, Team.id NULLS LAST LIMIT 4;

